INSERT INTO SQRHI (
       NO
     , IP
     , ADD_DATE
     , ADD_TIME
     , ACCESS_URL
     , HOUSE_CODE
     , COMPANY_CODE
     , SMR_NUMBER
     , SMD_NUMBER
     , LINK_CODE
) VALUES (
       ${NO}
     , ${ACCESS_IP}
     , ${current.DATE}
     , ${current.TIME}
     , ${ACCESS_URL}
     , ${HOUSE_CODE}
     , ${COMPANY_CODE}
     , ${SMR_NUMBER}
     , ${SMD_NUMBER}
     , ${LINK_CODE}
)
